INSERT INTO public.roadmap_items (title, description, notes, phase, status, sort_order) VALUES
('Micro-Outcome Moments في الدروس', 'block جديد كل ٢-٣ دروس يجاوب على سؤال "Why should I care?" — يربط المهارة بسيناريو حقيقي (فلوس/وقت/شغل)', '[source:ai] [scope:ui+content] من تحليل persona simulation: الـ Skeptic سأل "Why should I care?" 5/12 مرة. الحل: block type جديد microOutcome في intro-lesson-types.ts + renderer + ~٣٠ نقطة تحوّل في المسارات الـ ٥. الأولوية الأعلى للـ retention.', 'D', 'todo', 90001),
('Layered Truth — طبقتين لكل concept', 'كل concept فيه شرح سهل (default) + toggle "للمتقدمين" يكشف الحقيقة التقنية الكاملة', '[source:ai] [scope:ui+content] من تحليل persona simulation: الـ Expert Critic قيّم 5/12 درس "vague/oversimplified". الحل: field advancedNote في concepts block + disclosure UI + reapply على ~٢٠ درس تقني. يحمي المصداقية مع جمهور أوسع.', 'D', 'todo', 90002),
('Assistant as Core UX (مش زرار)', 'الـ assistant يبقى جزء أساسي من الدرس: proactive nudges + inline "اشرحلي أكتر" + mini panel دايماً ظاهر', '[source:ai] [scope:ui] من تحليل persona simulation: 6/6 personas استخدموا الـ assistant — ده core مش feature. تعديلات على AssistantPanel + IntroLessonRenderer + idle timer hook + Mini panel. الأكبر scope، آخر واحدة في الترتيب.', 'D', 'todo', 90003);